// This should be called when menu items, icons, or shortcuts have changed.
//
// Since: 2.5
func (m *Menu) Refresh() {
	// The refresh is handled by the driver when the menu is rendered
	// This method exists to trigger re-rendering in implementations
}

// MenuItem is a single item within any menu, it contains a display Label and Action function that is called when tapped.
type MenuItem struct {
	ChildMenu *Menu
	// Since: 2.1
	IsQuit      bool
	IsSeparator bool
	Label       string
	Action      func()
	// Since: 2.1
	Disabled bool
	// Since: 2.1
	Checked bool
	// Icon is an optional icon to display alongside the menu item label.
	//
	// Since: 2.5
	Icon Resource
	// Shortcut is an optional keyboard shortcut associated with the menu item.
	//
	// Since: 2.5
	Shortcut Shortcut
}

